import{_ as o,o as i,c as a,an as t}from"./chunks/framework.DwXRUCDv.js";const h=JSON.parse('{"title":"IDE Workflows for Julia","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/ide-workflows.md","filePath":"tutorials/ide-workflows.md","lastUpdated":null}'),r={name:"tutorials/ide-workflows.md"};function n(l,e,s,d,p,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="IDE-Workflows-for-Julia" tabindex="-1">IDE Workflows for Julia <a class="header-anchor" href="#IDE-Workflows-for-Julia" aria-label="Permalink to &quot;IDE Workflows for Julia {#IDE-Workflows-for-Julia}&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">Working in a good editor significantly improves the Julia experience. Choose whichever option fits your existing workflow best.</p><p></p></div><p>While the Julia REPL is powerful on its own, most users pair it with an IDE that provides syntax highlighting, inline documentation, and — most importantly — tight REPL integration so that code can be sent from a script to a live Julia session with a single keypress.</p><h2 id="VS-Code/VSCodium" tabindex="-1">VS Code/VSCodium <a class="header-anchor" href="#VS-Code/VSCodium" aria-label="Permalink to &quot;VS Code/VSCodium {#VS-Code/VSCodium}&quot;">​</a></h2><p><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a> is probably the most widely used editor for Julia development. <a href="https://vscodium.com/" target="_blank" rel="noreferrer">VSCodium</a> is a fully open-source build of VS Code without Microsoft telemetry, and is compatible with the same extensions.</p><p>Install the <strong><a href="https://marketplace.visualstudio.com/items?itemName=julialang.language-julia" target="_blank" rel="noreferrer">Julia extension</a></strong> (<code>julialang.language-julia</code>) to unlock:</p><ul><li><p>Integrated REPL — send lines or selections with <code>Shift+Enter</code></p></li><li><p>Inline evaluation results and variable display</p></li><li><p>Debugger, profiler, and plot pane</p></li><li><p>Workspace variable explorer and data viewer</p></li></ul><p>The extension can be installed from within the IDE via the <strong>Extensions panel</strong> (<code>Ctrl+Shift+X</code>) by searching for <code>Julia</code>.</p><h2 id="Positron" tabindex="-1">Positron <a class="header-anchor" href="#Positron" aria-label="Permalink to &quot;Positron {#Positron}&quot;">​</a></h2><p><a href="https://positron.posit.co/" target="_blank" rel="noreferrer">Positron</a> is an open-source fork of VS Code by Posit (makers of RStudio) with first-class support for both R and Python. It ships a dedicated <em>Connections</em>, <em>Variables</em>, and <em>Plots</em> pane out of the box, making it feel closer to RStudio for researchers coming from an R background.</p><p>There is also a dedicated <strong><a href="https://open-vsx.org/extension/ntluong95/positron-julia" target="_blank" rel="noreferrer">positron-julia extension</a></strong> available on Open VSX, installable via the Extensions panel. The <code>positron-julia</code> extension is in very early development and may be unstable.</p><h2 id="JetBrains-IDEs" tabindex="-1">JetBrains IDEs <a class="header-anchor" href="#JetBrains-IDEs" aria-label="Permalink to &quot;JetBrains IDEs {#JetBrains-IDEs}&quot;">​</a></h2><p><a href="https://www.jetbrains.com/" target="_blank" rel="noreferrer">JetBrains</a> offer Julia support via the <strong><a href="https://plugins.jetbrains.com/plugin/29356-flexible-julia" target="_blank" rel="noreferrer">Flexible Julia plugin</a></strong>. It should work in any JetBrains IDE (e.g., IntelliJ IDEA, PyCharm) and provides:</p><ul><li><p>Full language server support (completion, go-to-definition, refactoring)</p></li><li><p>Integrated Julia REPL within the IDE</p></li><li><p>Package manager UI</p></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">JetBrains IDEs are commercial software, though free community editions and academic licences are available.</p><p></p></div><h2 id="Neovim-Iron.nvim" tabindex="-1">Neovim + Iron.nvim <a class="header-anchor" href="#Neovim-Iron.nvim" aria-label="Permalink to &quot;Neovim + Iron.nvim {#Neovim-Iron.nvim}&quot;">​</a></h2><p>For terminal-focused workflows, <a href="https://neovim.io/" target="_blank" rel="noreferrer">Neovim</a> combined with <strong><a href="https://github.com/Vigemus/iron.nvim" target="_blank" rel="noreferrer">Iron.nvim</a></strong> provides a lightweight but highly capable environment:</p><ul><li><p><code>iron.nvim</code> opens a Julia REPL split and lets you send lines, visual selections, or entire files with configurable keymaps</p></li><li><p>Pair with <strong><a href="https://github.com/neovim/nvim-lspconfig" target="_blank" rel="noreferrer">nvim-lspconfig</a></strong> + the Julia language server (<code>julials</code>) for completion and diagnostics</p></li></ul>',18)])])}const m=o(r,[["render",n]]);export{h as __pageData,m as default};
